package com.example.demo; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.web.bind.annotation.RequestParam; import org.springframework.web.bind.annotation.RestController; import java.util.List; import java.util.Map; import java.util.Base64; @RestController public class LoginController { @Autowired private JdbcTemplate jdbcTemplate; @GetMapping("/users") public List<Map<String, Object>> getAllUsers() { return jdbcTemplate.queryForList("SELECT id, name, email FROM users"); } @GetMapping("/register") public String register(@RequestParam String name, @RequestParam String email, @RequestParam String password) { String encodedPass = Base64.getEncoder().encodeToString(password.getBytes()); jdbcTemplate.update("INSERT INTO users (name, email, password) VALUES (?, ?, ?)", name, email, encodedPass); return "User " + name + " Registered Safely!"; } @GetMapping("/login") public String login(@RequestParam String email, @RequestParam String password) { String encodedPass = Base64.getEncoder().encodeToString(password.getBytes()); List<Map<String, Object>> users = jdbcTemplate.queryForList("SELECT * FROM users WHERE email = ? AND password = ?", email, encodedPass); return !users.isEmpty() ? "Login Success!" : "Login Failed!"; } @GetMapping("/delete") public String deleteUser(@RequestParam int id) { jdbcTemplate.update("DELETE FROM users WHERE id = ?", id); return "User Deleted Successfully!"; } }
